1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root {
9	    --bg: #111418;
10	    --panel: #1b2027;
11	    --grid: #232a33;
12	    --text: #e8ecf1;
13	    --muted: #8b96a5;
14	    --I: #22c7e8;
15	    --O: #f2c613;
16	    --T: #a64ee0;
17	    --S: #3fc15a;
18	    --Z: #e8453c;
19	    --J: #3a6fe8;
20	    --L: #f08a24;
21	  }
22	  * { box-sizing: border-box; }
23	  body {
24	    margin: 0;
25	    min-height: 100vh;
26	    background: var(--bg);
27	    color: var(--text);
28	    font: 15px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
29	    display: flex;
30	    align-items: center;
31	    justify-content: center;
32	    padding: 16px;
33	  }
34	  .game { display: flex; gap: 20px; align-items: flex-start; flex-wrap: wrap; justify-content: center; }
35	  .board {
36	    display: grid;
37	    grid-template-columns: repeat(10, 28px);
38	    grid-template-rows: repeat(20, 28px);
39	    gap: 1px;
40	    background: var(--grid);
41	    border: 2px solid var(--grid);
42	    border-radius: 4px;
43	  }
44	  .cell { background: var(--bg); }
45	  .side { display: flex; flex-direction: column; gap: 12px; min-width: 140px; }
46	  .box { background: var(--panel); border-radius: 6px; padding: 10px 12px; }
47	  .label { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: .08em; }
48	  .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
49	  .preview {
50	    display: grid;
51	    grid-template-columns: repeat(4, 20px);
52	    grid-template-rows: repeat(2, 20px);
53	    gap: 1px;
54	    margin-top: 6px;
55	  }
56	  .preview div { background: transparent; }
57	  .next-list { display: flex; flex-direction: column; gap: 8px; }
58	  .board-wrap { position: relative; }
59	  .game-over {
60	    position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
61	    background: rgba(17, 20, 24, .78); font-size: 24px; font-weight: 600; border-radius: 4px;
62	  }
63	  .p-I { background: var(--I) !important; }
64	  .p-O { background: var(--O) !important; }
65	  .p-T { background: var(--T) !important; }
66	  .p-S { background: var(--S) !important; }
67	  .p-Z { background: var(--Z) !important; }
68	  .p-J { background: var(--J) !important; }
69	  .p-L { background: var(--L) !important; }
70	  button {
71	    background: var(--panel); color: var(--text); border: 1px solid var(--grid);
72	    border-radius: 6px; padding: 8px 12px; font: inherit; cursor: pointer;
73	  }
74	  button:hover { border-color: var(--muted); }
75	  .keys { color: var(--muted); font-size: 13px; }
76	</style>
77	</head>
78	<body>
79	<div class="game">
80	  <div class="board-wrap">
81	    <div class="board" data-testid="board" id="board"></div>
82	    <div class="game-over" data-testid="game-over" id="game-over" hidden>Game over</div>
83	  </div>
84	  <div class="side">
85	    <div class="box"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
86	    <div class="box"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
87	    <div class="box"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
88	    <div class="box"><div class="label">Next</div><div class="next-list" data-testid="next-piece" id="preview"></div></div>
89	    <button id="restart" type="button">New game</button>
90	    <div class="keys">← → move<br>↑ rotate<br>↓ soft drop<br>Space hard drop</div>
91	  </div>
92	</div>
93	<script>
94	(function () {
95	  "use strict";
96	
97	  var ROWS = 20, COLS = 10;
98	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
99	
100	  // Spawn shapes as [row, col] offsets from the piece origin.
101	  var SHAPES = {
102	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
103	    O: [[0, 1], [0, 2], [1, 1], [1, 2]],
104	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
105	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
106	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
107	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
108	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
109	  };
110	  // Side length of the square each shape rotates within.
111	  var BOX = { I: 4, O: 2, T: 3, S: 3, Z: 3, J: 3, L: 3 };
112	  var SPAWN_COL = 3;
113	  var GRAVITY_MS = 1000;
114	  // Preview rule (project decision): show only the next piece, in its board colour.
115	  var PREVIEW_COUNT = 1;
116	
117	  // Locking rule (project decision): a gravity step that cannot move the piece
118	  // down counts one lock tick; the piece locks on the LOCK_TICKS-th tick.
119	  // Left/right while resting restarts the delay, at most MAX_LOCK_RESETS times
120	  // per piece. Soft drop on a resting piece restarts it too, from the same
121	  // per-piece allowance. Hard drop locks at once.
122	  var LOCK_TICKS = 2;
123	  var MAX_LOCK_RESETS = 3;
124	  // Rotation tries these sideways shifts, in order, until one fits.
125	  var KICKS = [0, -1, 1, -2, 2];
126	
127	  // Scoring rule (project decision): a clear scores CLEAR_POINTS[rows] x level.
128	  // Clearing rows together must always beat clearing them one at a time.
129	  // Soft drop scores 1 per cell moved by the player (gravity scores nothing);
130	  // hard drop scores 2 per cell dropped. Drop points are not multiplied.
131	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
132	  var SOFT_DROP_POINTS = 1;
133	  var HARD_DROP_POINTS = 2;
134	
135	  var state = {
136	    board: [],      // ROWS x COLS, "" or piece letter
137	    current: null,  // { type, row, col, shape, lockTicks, lockResets }
138	    next: [],
139	    score: 0,
140	    level: 1,
141	    lines: 0,
142	    status: "running"
143	  };
144	
145	  // ---- core logic ----
146	
147	  function emptyBoard() {
148	    var b = [];
149	    for (var r = 0; r < ROWS; r++) {
150	      var row = [];
151	      for (var c = 0; c < COLS; c++) row.push("");
152	      b.push(row);
153	    }
154	    return b;
155	  }
156	
157	  function randomType() {
158	    return TYPES[Math.floor(Math.random() * TYPES.length)];
159	  }
160	
161	  function cellsOf(piece, dRow, dCol) {
162	    return piece.shape.map(function (o) {
163	      return [piece.row + (dRow || 0) + o[0], piece.col + (dCol || 0) + o[1]];
164	    });
165	  }
166	
167	  function fits(piece, dRow, dCol) {
168	    return cellsOf(piece, dRow, dCol).every(function (p) {
169	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && state.board[p[0]][p[1]] === "";
170	    });
171	  }
172	
173	  function spawn() {
174	    var type = state.next.length ? state.next.shift() : randomType();
175	    while (state.next.length < PREVIEW_COUNT) state.next.push(randomType());
176	    var piece = { type: type, row: 0, col: SPAWN_COL, shape: SHAPES[type], lockTicks: 0, lockResets: 0 };
177	    // Game over: the new piece has nowhere to go. It is not placed.
178	    if (!fits(piece, 0, 0)) {
179	      state.current = null;
180	      state.status = "gameover";
181	      return;
182	    }
183	    state.current = piece;
184	  }
185	
186	  function lock() {
187	    var piece = state.current;
188	    cellsOf(piece).forEach(function (p) { state.board[p[0]][p[1]] = piece.type; });
189	    state.current = null;
190	    clearLines();
191	    spawn();
192	  }
193	
194	  // Remove every full row; rows above drop down. Scores the clear.
195	  function clearLines() {
196	    var kept = state.board.filter(function (row) {
197	      return row.some(function (t) { return t === ""; });
198	    });
199	    var cleared = ROWS - kept.length;
200	    if (!cleared) return;
201	    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
202	    state.board = kept;
203	    state.lines += cleared;
204	    state.score += CLEAR_POINTS[cleared] * state.level;
205	  }
206	
207	  function tryMove(dRow, dCol) {
208	    if (!state.current || !fits(state.current, dRow, dCol)) return false;
209	    state.current.row += dRow;
210	    state.current.col += dCol;
211	    if (dRow > 0) state.current.lockTicks = 0;
212	    return true;
213	  }
214	
215	  // If the lock delay is running, restart it (capped per piece).
216	  function resetLockDelay(piece) {
217	    if (piece.lockTicks > 0 && piece.lockResets < MAX_LOCK_RESETS) {
218	      piece.lockResets++;
219	      piece.lockTicks = 0;
220	    }
221	  }
222	
223	  function shift(dCol) {
224	    var piece = state.current;
225	    if (!tryMove(0, dCol)) return;
226	    resetLockDelay(piece);
227	  }
228	
229	  function rotateCW() {
230	    var piece = state.current;
231	    if (!piece || piece.type === "O") return;
232	    var n = BOX[piece.type];
233	    var turned = {
234	      type: piece.type, row: piece.row, col: piece.col,
235	      shape: piece.shape.map(function (o) { return [o[1], n - 1 - o[0]]; })
236	    };
237	    for (var i = 0; i < KICKS.length; i++) {
238	      if (fits(turned, 0, KICKS[i])) {
239	        piece.shape = turned.shape;
240	        piece.col += KICKS[i];
241	        return;
242	      }
243	    }
244	  }
245	
246	  // One gravity step. The timer and __tetris.tick both call this.
247	  function gravityStep() {
248	    if (state.status !== "running" || !state.current) return;
249	    if (tryMove(1, 0)) return;
250	    state.current.lockTicks++;
251	    if (state.current.lockTicks >= LOCK_TICKS) lock();
252	  }
253	
254	  var actions = {
255	    left: function () { if (state.current) shift(-1); },
256	    right: function () { if (state.current) shift(1); },
257	    rotateCW: rotateCW,
258	    softDrop: function () {
259	      if (!state.current) return;
260	      if (tryMove(1, 0)) state.score += SOFT_DROP_POINTS;
261	      else resetLockDelay(state.current);
262	    },
263	    hardDrop: function () {
264	      if (!state.current) return;
265	      while (tryMove(1, 0)) state.score += HARD_DROP_POINTS;
266	      lock();
267	    }
268	  };
269	
270	  function doAction(name) {
271	    if (state.status !== "running" || !actions[name]) return;
272	    actions[name]();
273	    render();
274	  }
275	
276	  function newGame(queue) {
277	    state.board = emptyBoard();
278	    state.score = 0;
279	    state.level = 1;
280	    state.lines = 0;
281	    state.status = "running";
282	    state.next = Array.isArray(queue) ? queue.slice() : [];
283	    spawn();
284	    restartTimer();
285	    render();
286	  }
287	
288	  // ---- rendering (synchronous) ----
289	
290	  var boardEl = document.getElementById("board");
291	  var previewEl = document.getElementById("preview");
292	  var scoreEl = document.getElementById("score");
293	  var levelEl = document.getElementById("level");
294	  var linesEl = document.getElementById("lines");
295	  var gameOverEl = document.getElementById("game-over");
296	  var cellEls = [];
297	
298	  (function buildDom() {
299	    for (var r = 0; r < ROWS; r++) {
300	      var row = [];
301	      for (var c = 0; c < COLS; c++) {
302	        var el = document.createElement("div");
303	        el.className = "cell";
304	        el.setAttribute("data-testid", "cell");
305	        el.setAttribute("data-row", String(r));
306	        el.setAttribute("data-col", String(c));
307	        el.setAttribute("data-filled", "false");
308	        el.setAttribute("data-piece", "");
309	        boardEl.appendChild(el);
310	        row.push(el);
311	      }
312	      cellEls.push(row);
313	    }
314	  })();
315	
316	  // One preview item per previewed piece, drawn in its board colour.
317	  function previewItem(type) {
318	    var item = document.createElement("div");
319	    item.className = "preview";
320	    item.setAttribute("data-testid", "next-piece-item");
321	    item.setAttribute("data-piece", type);
322	    var cells = [];
323	    for (var i = 0; i < 8; i++) cells.push(item.appendChild(document.createElement("div")));
324	    SHAPES[type].forEach(function (o) { paint(cells[o[0] * 4 + o[1]], type); });
325	    return item;
326	  }
327	
328	  function paint(el, type) {
329	    el.className = el.className.replace(/\s*p-[A-Z]/g, "") + (type ? " p-" + type : "");
330	  }
331	
332	  function render() {
333	    var view = state.board.map(function (row) { return row.slice(); });
334	    if (state.current) {
335	      cellsOf(state.current).forEach(function (p) {
336	        if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) view[p[0]][p[1]] = state.current.type;
337	      });
338	    }
339	    for (var r = 0; r < ROWS; r++) {
340	      for (var c = 0; c < COLS; c++) {
341	        var el = cellEls[r][c], t = view[r][c];
342	        el.setAttribute("data-filled", t ? "true" : "false");
343	        el.setAttribute("data-piece", t);
344	        paint(el, t);
345	      }
346	    }
347	    previewEl.textContent = "";
348	    state.next.slice(0, PREVIEW_COUNT).forEach(function (type) {
349	      if (SHAPES[type]) previewEl.appendChild(previewItem(type));
350	    });
351	    gameOverEl.hidden = state.status !== "gameover";
352	    scoreEl.textContent = String(state.score);
353	    levelEl.textContent = String(state.level);
354	    linesEl.textContent = String(state.lines);
355	  }
356	
357	  // ---- timer ----
358	
359	  var timer = null;
360	  function onTimer() { gravityStep(); render(); }
361	  function restartTimer() {
362	    if (timer) clearInterval(timer);
363	    timer = setInterval(onTimer, GRAVITY_MS);
364	  }
365	
366	  // ---- input ----
367	
368	  var KEYS = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", " ": "hardDrop" };
369	  document.addEventListener("keydown", function (e) {
370	    var action = KEYS[e.key];
371	    if (!action) return;
372	    e.preventDefault();
373	    doAction(action);
374	  });
375	  document.getElementById("restart").addEventListener("click", function (e) {
376	    e.currentTarget.blur();
377	    newGame();
378	  });
379	
380	  // ---- test control surface ----
381	
382	  window.__tetris = {
383	    newGame: function (queue) { newGame(queue); },
384	    setQueue: function (queue) {
385	      state.next = Array.isArray(queue) ? queue.slice() : [];
386	      render();
387	    },
388	    setBoard: function (rows) {
389	      state.board = rows.map(function (line) {
390	        return line.split("").map(function (ch) { return ch === "." ? "" : ch; });
391	      });
392	      render();
393	    },
394	    tick: function (n) {
395	      var steps = n === undefined ? 1 : n;
396	      for (var i = 0; i < steps; i++) gravityStep();
397	      render();
398	    },
399	    input: function (action) { doAction(action); },
400	    getBoard: function () {
401	      return state.board.map(function (row) {
402	        return row.map(function (t) { return t || "."; }).join("");
403	      });
404	    },
405	    getState: function () {
406	      return {
407	        current: state.current
408	          ? { type: state.current.type, cells: cellsOf(state.current) }
409	          : null,
410	        next: state.next.slice(),
411	        score: state.score,
412	        level: state.level,
413	        lines: state.lines,
414	        status: state.status
415	      };
416	    }
417	  };
418	
419	  newGame();
420	})();
421	</script>
422	</body>
423	</html>
