p='index.html'; s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1, a
    s=s.replace(a,b)
rep('''    <div class="box"><div class="label">Next</div>''','''    <div class="box"><div class="label">Hold</div><div class="preview" data-testid="hold-piece" data-piece="" id="hold"></div></div>
    <div class="box"><div class="label">Next</div>''')
rep('''Space hard drop</div>''','''Space hard drop<br>C hold</div>''')
rep('''  var GRAVITY_MS = 1000;
''','''  // Level rule (project decision): level starts at 1 and rises by one for every
  // LINES_PER_LEVEL lines cleared; it never goes down. Gravity interval in ms is
  // max(MIN_GRAVITY_MS, BASE_GRAVITY_MS - (level - 1) * GRAVITY_STEP_MS).
  // __tetris.tick(n) always advances exactly n gravity steps, whatever the level.
  var LINES_PER_LEVEL = 10;
  var BASE_GRAVITY_MS = 1000;
  var GRAVITY_STEP_MS = 100;
  var MIN_GRAVITY_MS = 100;
  // Hold rule (project decision): one slot. Holding with an empty slot sets the
  // falling piece aside and spawns the next one; otherwise it swaps with the held
  // piece, which enters at the spawn position. One hold per piece: a second hold
  // is refused until a piece locks.
''')
rep('''    next: [],
    score''','''    next: [],
    hold: null,     // held piece letter or null
    canHold: true,
    score''')
rep('''  function spawn() {
    var type = state.next.length ? state.next.shift() : randomType();
    while (state.next.length < PREVIEW_COUNT) state.next.push(randomType());
''','''  function dropInterval() {
    return Math.max(MIN_GRAVITY_MS, BASE_GRAVITY_MS - (state.level - 1) * GRAVITY_STEP_MS);
  }

  function spawn() {
    var type = state.next.length ? state.next.shift() : randomType();
    while (state.next.length < PREVIEW_COUNT) state.next.push(randomType());
    spawnType(type);
  }

  function spawnType(type) {
''')
rep('''    state.current = null;
    clearLines();''','''    state.current = null;
    state.canHold = true;
    clearLines();''')
rep('''    state.lines += cleared;
    state.score += CLEAR_POINTS[cleared] * state.level;
''','''    var before = Math.floor(state.lines / LINES_PER_LEVEL);
    state.lines += cleared;
    state.score += CLEAR_POINTS[cleared] * state.level;
    var gained = Math.floor(state.lines / LINES_PER_LEVEL) - before;
    if (gained > 0) {
      state.level += gained;
      restartTimer();
    }
''')
rep('''      lock();
    }
  };''','''      lock();
    },
    hold: function () {
      if (!state.current || !state.canHold) return;
      var type = state.current.type;
      state.canHold = false;
      if (state.hold) {
        var held = state.hold;
        state.hold = type;
        spawnType(held);
      } else {
        state.hold = type;
        spawn();
      }
    }
  };''')
rep('''    state.lines = 0;
    state.status = "running";''','''    state.lines = 0;
    state.hold = null;
    state.canHold = true;
    state.status = "running";''')
rep('''  var gameOverEl = document.getElementById("game-over");
  var cellEls = [];
''','''  var gameOverEl = document.getElementById("game-over");
  var holdEl = document.getElementById("hold");
  var cellEls = [];
  var holdCells = [];
  for (var h = 0; h < 8; h++) holdCells.push(holdEl.appendChild(document.createElement("div")));
''')
rep('''    gameOverEl.hidden''','''    holdEl.setAttribute("data-piece", state.hold || "");
    holdCells.forEach(function (el) { paint(el, ""); });
    if (state.hold) SHAPES[state.hold].forEach(function (o) { paint(holdCells[o[0] * 4 + o[1]], state.hold); });
    gameOverEl.hidden''')
rep('''    timer = setInterval(onTimer, GRAVITY_MS);''','''    timer = setInterval(onTimer, dropInterval());''')
rep('''" ": "hardDrop" };''','''" ": "hardDrop", c: "hold", C: "hold" };''')
rep('''    input: function (action) { doAction(action); },''','''    setLevel: function (n) {
      state.level = n;
      restartTimer();
      render();
    },
    input: function (action) { doAction(action); },''')
rep('''        level: state.level,
        lines''','''        level: state.level,
        dropInterval: dropInterval(),
        hold: state.hold,
        lines''')
open(p,'w').write(s)
EOF
